L["/dui buffs test [0-1 | N% | off] - preview a sample of every known buff"] = "/dui buffs test [0-1 | N% | off] - zeigt eine Vorschau mit Beispielen aller bekannten Buffs"
L["/dui buffs debug - what each bar is doing"] = "/dui buffs debug - zeigt, was jede Leiste gerade tut"
L["Usage: /dui buffs toggle <category name>"] = "Verwendung: /dui buffs toggle <Kategoriename>"
L["No category called '%s'."] = "Keine Kategorie namens „%s“."
L["%s hidden."] = "%s ausgeblendet."
L["%s shown."] = "%s eingeblendet."
L["Unknown command '%s'."] = "Unbekannter Befehl „%s“."
L["Preview on: %d sample buffs. /dui buffs test off to stop; /dui buffs test 100%% for all."] = "Vorschau an: %d Beispielbuffs. Beenden mit /dui buffs test off, alle zeigen mit /dui buffs test 100%%."
L["Preview on: %d%% of known buffs. /dui buffs test off to stop."] = "Vorschau an: %d%% der bekannten Buffs. Beenden mit /dui buffs test off."
L["Preview off."] = "Vorschau aus."
L["Group auras are not readable right now (restricted by the client). Try again out of combat."] = "Die Auren der Gruppe lassen sich gerade nicht auslesen (vom Client gesperrt). Versuche es außerhalb des Kampfes erneut."
L["No unrecognized buffs on the group."] = "Keine unerkannten Buffs in der Gruppe."
L["1 unrecognized buff on the group:"] = "1 unerkannter Buff in der Gruppe:"
L["%d unrecognized buffs on the group:"] = "%d unerkannte Buffs in der Gruppe:"
L["  %s (on %s) - caster is a %s"] = "  %s (auf %s) - Klasse des Zaubernden: %s"
L["  %s (on %s)"] = "  %s (auf %s)"

-- DaylightUI_Skins: checked by a native speaker.
L["Game window skins"] = "Spielfenster-Skins"
L["The game's windows Daylight UI didn't rebuild. Rebuilt windows have their own switches under Extras."] = "Spielfenster, die Daylight UI nicht selbst nachbaut. Nachgebaute Fenster haben eigene Schalter unter „Extras“."
L["Flight maps, stable and books"] = "Flugkarten, Stall und Bücher"
L["Flight maps, books and letters, tabards and petitions, the stable."] = "Flugkarten, Bücher und Briefe, Wappenröcke und Satzungen, der Stall."
L["Guild, calendar and trading"] = "Gilde, Kalender und Handel"
L["Guild and communities, the calendar, trading, the guild bank."] = "Gilde und Communitys, Kalender, Handel und Gildenbank."
L["Collections and journals"] = "Sammlungen und Kompendien"
L["Collections, achievements, the dungeon journal, the dressing room."] = "Sammlungen, Erfolge, Dungeonkompendium und Anprobe."
L["Menus, loot and items"] = "Menüs, Beute und Gegenstände"
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the box that splits a stack."] = "Spielmenü, Addon-Liste, Makros, Uhr, Beute, Sockeln, Aufwerten, Verschrotter, Auktionshaus, Berufsbuch, der Rahmen der Weltkarte, die Atemleiste und das Feld zum Teilen eines Stapels."
L["Windows"] = "Fenster"
L["Breath bar"] = "Atemleiste"
L["Breath bar angled end"] = "Atemleiste abschrägen"
L["Cuts the right end of the breath bar at an angle, on the fatigue and feign death bars too. When off, the end is straight."] = "Schrägt das rechte Ende der Atemleiste ab, auch bei den Leisten für Erschöpfung und Totstellen. Sonst ist das Ende gerade."
L["Crowd control alert"] = "Warnung bei Massenkontrolle"
L["CC alert"] = "Warnung bei Massenkontrolle"
L["The alert in the middle of the screen when you're stunned, feared or silenced, as a light line in Daylight UI style. When off, the game's own alert shows instead."] = "Die Warnung in der Bildschirmmitte, wenn du betäubt, verängstigt oder zum Schweigen gebracht bist, als schlanke Linie im Daylight-UI-Stil. Sonst erscheint die Warnung des Spiels."
L["Other addons"] = "Andere Addons"
L["World map"] = "Weltkarte"
L["Quest list beside the map"] = "Questliste neben der Karte"
L["With the map maximized, the quest list opens beside it, as it does on the small map, instead of taking its room from the map. On a narrow screen the map gives up only what doesn't fit."] = "Ist die Karte maximiert, öffnet sich die Questliste daneben wie bei der kleinen Karte, statt der Karte Platz wegzunehmen. Auf einem schmalen Bildschirm gibt die Karte nur so viel Platz ab wie nötig."
L["Show unexplored areas"] = "Unerforschte Gebiete anzeigen"
L["Parts of the world map you haven't explored yet show too, dimmed so you can still tell where you haven't been."] = "Zeigt auch die Teile der Weltkarte, die du noch nicht erforscht hast. Sie sind abgedunkelt, damit du weiter erkennst, wo du noch nicht warst."
L["Unexplored area brightness"] = "Helligkeit unerforschter Gebiete"
L["How bright the unexplored areas are. At 100% they look like the parts you've explored."] = "Helligkeit der unerforschten Gebiete. Bei 100% sehen sie aus wie die bereits erforschten."
L["Dungeon and raid entrances"] = "Dungeon- und Schlachtzugseingänge"
L["A symbol on the world map at each dungeon and raid entrance. Hover it for the name."] = "Ein Symbol auf der Weltkarte an jedem Dungeon- und Schlachtzugseingang. Zeige mit der Maus darauf, um den Namen zu sehen."
L["Flight masters"] = "Flugmeister"
L["A bird on the world map at each flight master you can use: blue for Alliance, red for Horde, gold for both."] = "Ein Vogel auf der Weltkarte bei jedem Flugmeister, den du nutzen kannst: blau für die Allianz, rot für die Horde, golden für beide."
L["Boats and zeppelins"] = "Schiffe und Zeppeline"
L["A symbol on the world map at each boat dock and zeppelin tower. Hover it to see where it goes."] = "Ein Symbol auf der Weltkarte an jedem Anleger und Zeppelinturm. Zeige mit der Maus darauf, um das Ziel zu sehen."
L["Other faction's flight masters"] = "Flugmeister der anderen Fraktion"
L["Show the other faction's flight masters on the world map as well, in their own color. Handy for knowing where the enemy flies from."] = "Zeigt auch die Flugmeister der anderen Fraktion auf der Weltkarte, in deren eigener Farbe. Praktisch, um zu wissen, wo der Gegner losfliegt."
L["Map symbol scale"] = "Größe der Kartensymbole"
L["The size of the entrance, flight master, boat and zeppelin symbols on the world map. They keep this size as you zoom."] = "Größe der Symbole für Eingänge, Flugmeister, Schiffe und Zeppeline auf der Weltkarte. Beim Zoomen bleibt die Größe gleich."
L["Map symbol opacity"] = "Deckkraft der Kartensymbole"
L["Dungeon"] = "Dungeon"
L["Raid, %d players"] = "Schlachtzug, %d Spieler"
L["Flight master"] = "Flugmeister"
L["Boat to %s"] = "Schiff nach %s"
L["Zeppelin to %s"] = "Zeppelin nach %s"
L["Addon options (Ace3)"] = "Addon-Optionen (Ace3)"
L["Options windows of addons built on Ace3, in the game's settings and their own windows: Questie, RestedXP and many more."] = "Optionsfenster von Addons auf Ace3-Basis, in den Spieleinstellungen und in eigenen Fenstern: Questie, RestedXP und viele mehr."
L["Ace3"] = "Ace3"
L["Attune"] = "Attune"
L["Its window, and each attunement chain drawn like the talent trees."] = "Das Fenster des Addons. Jede Kette von Zugangsquests sieht aus wie ein Talentbaum."
L["Baganator"] = "Baganator"
L["Its bag, bank and guild bank windows, slots, buttons and settings, while its own Blizzard look is picked."] = "Taschen-, Bank- und Gildenbankfenster, Plätze, Buttons und Einstellungen, solange in Baganator der Stil „Blizzard“ gewählt ist."
L["Bagnon"] = "Bagnon"
L["Its bag, bank and guild bank windows, slots and buttons. Another look can still be picked in Bagnon's own options."] = "Taschen-, Bank- und Gildenbankfenster, Plätze und Buttons. In den Optionen von Bagnon kannst du weiterhin einen anderen Stil wählen."
L["The Daylight UI look."] = "Der Stil von Daylight UI."
L["BigWigs and LittleWigs"] = "BigWigs und LittleWigs"
L["Their timer bars in your font, bar texture and border, on BigWigs' Default bar style. Sizes, colors and spots stay BigWigs'."] = "Die Timerleisten mit deiner Schrift, Leistentextur und deinem Rand, im Leistenstil „Standard“ von BigWigs. Größen, Farben und Positionen legt weiter BigWigs fest."
L["Deadly Boss Mods"] = "Deadly Boss Mods"
L["Its timer bars in your font, bar texture and border. Sizes, colors and spots stay DBM's."] = "Die Timerleisten mit deiner Schrift, Leistentextur und deinem Rand. Größen, Farben und Positionen legt weiter DBM fest."
L["Dungeon Journal"] = "Dungeonkompendium"
L["The dungeon journal, its favorites and settings windows; each dungeon's picture kept."] = "Das Dungeonkompendium mit Favoriten- und Einstellungsfenster. Die Bilder der Dungeons bleiben erhalten."
L["NeedRoll"] = "NeedRoll"
L["The loot browser's window, its lists, buttons and dialogs; its icons and maps kept."] = "Das Fenster des Beutebrowsers mit Listen, Buttons und Dialogen. Symbole und Karten bleiben erhalten."
L["OPie"] = "OPie"
L["Its ring buttons in your action bar look. The ring, its spin and its options stay OPie's."] = "Die Ring-Buttons im Stil deiner Aktionsleisten. Den Ring, seine Drehung und seine Optionen legt weiter OPie fest."
L["PrettyTooltip"] = "PrettyTooltip"
L["Its tooltips in the Daylight UI frame, in your background opacity. Its layout, words and stat colors stay."] = "Die Tooltips im Rahmen von Daylight UI und mit deiner Hintergrunddeckkraft. Layout, Texte und die Farben der Werte bleiben."
L["Questie"] = "Questie"
L["Its options and My Journey windows, and its quest objective icons on the maps, each quest in its own color."] = "Die Fenster für Optionen und „Meine Reise“ sowie die Symbole der Questziele auf den Karten, jede Quest in eigener Farbe."
L["RestedXP Guides"] = "RestedXP Guides"
L["The guide window (old and new), its steps and its item and target boxes."] = "Das Fenster der Guides (alt und neu), die Schritte und die Felder für Gegenstände und Ziele."
