L["Clear moved items"] = "Verschiebungen aufheben"
L["Every item you dragged onto a group, or moved with Alt-right-click, goes back to its own group."] = "Jeder Gegenstand, den du auf eine Gruppe gezogen oder per Alt-Rechtsklick verschoben hast, kommt zurück in seine eigene Gruppe."
L["Bring back a group"] = "Gruppe zurückholen"
L["A group you deleted comes back, with its items."] = "Holt eine gelöschte Gruppe samt ihren Gegenständen zurück."
L["Share your groups"] = "Gruppen teilen"
