L["Export bag groups"] = "Taschengruppen exportieren"
L["Your own groups: their names, searches and the items you moved to them. Ctrl+C to copy, then share it."] = "Deine eigenen Gruppen: Namen, Suchen und die Gegenstände, die du hineingelegt hast. Kopiere den Text mit Strg+C und teile ihn."
L["Your own groups as text to copy: paste it on another character, or give it to a friend."] = "Deine eigenen Gruppen als Text zum Kopieren. Füge ihn bei einem anderen Charakter ein oder gib ihn an Freunde weiter."
L["Import groups"] = "Gruppen importieren"
L["Import bag groups"] = "Taschengruppen importieren"
L["Paste bag groups (Ctrl+V), from Daylight UI or Baganator. A group with the same name as one of yours is updated; the others are added."] = "Füge Taschengruppen aus Daylight UI oder Baganator ein (Strg+V). Gruppen mit dem Namen einer deiner Gruppen werden aktualisiert, die übrigen hinzugefügt."
L["Only items moved to Baganator's own categories: they go to the same groups here."] = "Nur Gegenstände, die in Baganators eigene Kategorien verschoben wurden. Sie kommen hier in dieselben Gruppen."
