L["Friendly players' names when Friendly name color is Custom colors."] = "Namen freundlicher Spieler, wenn „Farbe freundlicher Namen“ auf „Eigene Farben“ steht."
L["Friendly power bar"] = "Freundliche Ressourcenleiste"
L["Friendly health text % sign"] = "%-Zeichen im freundlichen Gesundheitstext"
L["Friendly name color"] = "Farbe freundlicher Namen"
L["Friendly NPC jobs"] = "Freundliche NSC-Berufe"
