L["Color to full color"] = "Übergang zur Maximalfarbe"
L["Slant angle"] = "Schrägwinkel"
L["The fill of the combo points. General uses the bar texture on General > Appearance."] = "Die Füllung der Combopunkte. „Allgemein“ übernimmt die Leistentextur von Allgemein > Erscheinungsbild."
L["Party and raid frames fade to their own opacity instead of the one above."] = "Gruppen- und Schlachtzugsrahmen nutzen eine eigene Restdeckkraft statt der darüber."
