L["Button 5"] = "Maustaste 5"
L["Ctrl"] = "Strg"
L["Shift"] = "Umschalt"
L["Alt"] = "Alt"
L["Spell %s"] = "Zauber %s"
L["not known now"] = "derzeit nicht erlernt"
L["No spells bound yet."] = "Noch keine Zauber zugewiesen."
