L["Shows each pet's name."] = "Zeigt den Namen jedes Begleiters."
L["Show the damage role icon"] = "Rollensymbol für Schaden anzeigen"
L["Leader crown pixel size"] = "Pixelgröße der Anführerkrone"
L["The pets' names. General uses the font on General > Appearance."] = "Die Namen der Begleiter. „Allgemein“ übernimmt die Schrift von Allgemein > Erscheinungsbild."
L["Left of its owner"] = "Links vom Besitzer"
L["Show leader crown in combat"] = "Anführerkrone im Kampf anzeigen"
