L["Quest count"] = "Questfortschritt"
L["A green sliver on the health bar for heals on their way, as the unit frames show them."] = "Ein grüner Streifen auf der Gesundheitsleiste für ankommende Heilungen, wie bei den Einheitenrahmen."
L["Shields"] = "Schilde"
L["A pale sliver on the health bar for an absorb shield, as the unit frames show them."] = "Ein blasser Streifen auf der Gesundheitsleiste für Absorptionsschilde, wie bei den Einheitenrahmen."
L["A small skull by the bar once your damage over time is enough to finish that enemy."] = "Ein kleiner Totenkopf neben der Leiste, sobald der Schaden deiner DoTs reicht, um den Gegner zu töten."
L["Guild names"] = "Gildennamen"
