L["NPC jobs"] = "NSC-Berufe"
L["What an NPC does (Skinner, Flight Master...) under its name, smaller. Not inside instances."] = "Der Beruf eines NSCs (Kürschner, Flugmeister...) in kleinerer Schrift unter seinem Namen. Nicht in Instanzen."
L["Job color"] = "Berufsfarbe"
L["NPC jobs in soft tan, plain white, or one color."] = "NSC-Berufe in sanftem Beige, in schlichtem Weiß oder in einer Farbe deiner Wahl."
