L["The tag after an elite quest's title."] = "Das Kennzeichen hinter dem Titel einer Elitequest."
L["The order of the quests inside each zone in the quest log on the map."] = "Reihenfolge der Quests innerhalb jeder Zone im Questlog auf der Karte."
L["Quest log order"] = "Wie im Questlog"
L["A small dot in front of each quest you're tracking."] = "Ein kleiner Punkt vor jeder verfolgten Quest."
