L["Quest log sort order"] = "Sortierung im Questlog"
L["Writes zone names in capital letters. When off, they're written as the game writes them."] = "Schreibt Zonennamen in Großbuchstaben. Sonst bleibt die Schreibweise des Spiels."
L["Quest log"] = "Questlog"
L["Quest list"] = "Questliste"
L["Quest tooltips beside the log"] = "Quest-Tooltips neben dem Log"
L["Show quest levels in the quest log"] = "Queststufen im Questlog anzeigen"
L["Puts the zone you're in at the top of the quest log. When off, zones stay in the game's order."] = "Setzt deine aktuelle Zone an den Anfang des Questlogs. Sonst bleiben die Zonen in der Reihenfolge des Spiels."
L["Show progress in the quest log"] = "Fortschritt im Questlog anzeigen"
L["How solid the quest log's background is. Lower lets the world show through behind the list."] = "Deckkraft des Questlog-Hintergrunds. Niedrigere Werte lassen die Welt hinter der Liste durchscheinen."
L["Counts like 0/6, and Ready, at the end of each quest's row."] = "Zähler wie 0/6 und „Bereit“ am Ende jeder Questzeile."
